def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_p_not_multiple_of_11(n):
    """
    Checks if P(n) = S(n)S(n+1)...S(n+37) is NOT a multiple of 11.
    This is equivalent to checking if S(k) is NOT a multiple of 11 for all k in [n, n+37].
    """
    for k in range(n, n + 38):
        s_k = sum_digits(k)
        if s_k % 11 == 0:
            # If any factor S(k) is a multiple of 11, P(n) is a multiple of 11
            return False
    # If no factor S(k) is a multiple of 11, P(n) is NOT a multiple of 11
    return True

# Search range: n=501 up to n=2000
start_n = 501
end_n = 2001 # Check up to n=2000 inclusive

found_n = -1

for n in range(start_n, end_n):
    if check_p_not_multiple_of_11(n):
        found_n = n
        break

if found_n != -1:
